mapper.update:
UPDATE user u SET u.blog_count = (
    SELECT COUNT(*) FROM blog b WHERE b.user_id = u.id
);

UPDATE user u SET u.likes_count = (
    SELECT COUNT(*) FROM likes l 
    JOIN blog b ON l.fid = b.id 
    WHERE l.module = '博客' AND b.user_id = u.id
);

UPDATE user u SET u.collect_count = (
    SELECT COUNT(*) FROM collect c 
    JOIN blog b ON c.fid = b.id 
    WHERE c.module = '博客' AND b.user_id = u.id
);
